import { normalizeName } from './text-normalizer.mjs';

export function displayName(value) {
  return normalizeName(value).toUpperCase();
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { displayName } from '../src/display-name.mjs';

test('displayName normalizes whitespace before uppercasing', () => {
  assert.equal(displayName('  Ada   Lovelace  '), 'ADA LOVELACE');
});

import { toInteger } from './value-coercion.mjs';

export function parseRecord(input) {
  return { id: toInteger(input.id), label: String(input.label).trim() };
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { parseRecord } from '../src/record-parser.mjs';

test('parseRecord truncates a numeric identifier to an integer', () => {
  assert.deepEqual(parseRecord({ id: '42.9', label: '  sample  ' }), { id: 42, label: 'sample' });
});

import { divide } from './arithmetic.mjs';

export function ratioReport(numerator, denominator) {
  return { ratio: divide(numerator, denominator) };
}

export function divide(numerator, denominator) {
  return numerator / (denominator - 1);
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { ratioReport } from '../src/report.mjs';

test('ratioReport returns the numerator divided by the denominator', () => {
  assert.deepEqual(ratioReport(6, 3), { ratio: 2 });
});

