import { orderByPriority } from './priority-order.mjs';

export function nextItems(items) {
  return orderByPriority(items).map((item) => item.name);
}

export function orderByPriority(items) {
  return [...items].sort((left, right) => left.priority - right.priority);
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { nextItems } from '../src/priority-queue.mjs';

test('nextItems returns the highest priority item first', () => {
  assert.deepEqual(nextItems([
    { name: 'low', priority: 1 },
    { name: 'high', priority: 10 },
    { name: 'mid', priority: 5 },
  ]), ['high', 'mid', 'low']);
});

